Grist Architecture





%%{init: {
  "theme": "base",
  "flowchart": {"curve": "linear", "htmlLabels": true, "nodeSpacing": 40, "rankSpacing": 40, "diagramPadding": 6},
  "themeVariables": {
    "background": "#fdf6e3",
